import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const PATTERN = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
const NUMERIC = /^[0-9]+$/;
const CORE = ['major', 'minor', 'patch'];

function parse(version) {
  if (typeof version !== 'string') throw new Error('Invalid version');
  const match = PATTERN.exec(version);
  // Checking the entire match also rejects a trailing newline accepted by $.
  if (!match || match[0] !== version) throw new Error('Invalid version');
  const prerelease = match[4] === undefined ? [] : match[4].split('.');
  if (prerelease.some(id => NUMERIC.test(id) && id.length > 1 && id[0] === '0')) {
    throw new Error('Invalid numeric prerelease identifier');
  }
  return { major: match[1], minor: match[2], patch: match[3], prerelease };
}

function compareNumeric(a, b) {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a === b ? 0 : a < b ? -1 : 1;
}

function compareParsed(a, b) {
  for (const key of CORE) {
    const result = compareNumeric(a[key], b[key]);
    if (result !== 0) return result;
  }
  const left = a.prerelease, right = b.prerelease;
  if (!left.length || !right.length) {
    return left.length === right.length ? 0 : left.length ? -1 : 1;
  }
  for (let i = 0; i < Math.min(left.length, right.length); i++) {
    if (left[i] === right[i]) continue;
    const leftNumeric = NUMERIC.test(left[i]), rightNumeric = NUMERIC.test(right[i]);
    if (leftNumeric && rightNumeric) return compareNumeric(left[i], right[i]);
    if (leftNumeric !== rightNumeric) return leftNumeric ? -1 : 1;
    return left[i] < right[i] ? -1 : 1;
  }
  return left.length === right.length ? 0 : left.length < right.length ? -1 : 1;
}

export function compareVersions(a, b) {
  return compareParsed(parse(a), parse(b));
}

function parseRange(range) {
  if (typeof range !== 'string') throw new Error('Invalid range');
  return range.split('||').map(clause => {
    if (!clause.trim()) throw new Error('Empty range clause');
    return clause.trim().split(/\s+/).map(text => {
      const match = /^(<=|>=|=|<|>)?(.*)$/.exec(text);
      return { operator: match[1] ?? '=', version: parse(match[2]) };
    });
  });
}

function satisfiesParsed(version, clauses) {
  return clauses.some(clause => {
    if (version.prerelease.length && !clause.some(comparator =>
      comparator.version.prerelease.length &&
      CORE.every(key => version[key] === comparator.version[key]))) return false;
    return clause.every(comparator => {
      const result = compareParsed(version, comparator.version);
      switch (comparator.operator) {
        case '=': return result === 0;
        case '<': return result < 0;
        case '<=': return result <= 0;
        case '>': return result > 0;
        case '>=': return result >= 0;
      }
    });
  });
}

export function satisfies(version, range) {
  return satisfiesParsed(parse(version), parseRange(range));
}

function runCli() {
  try {
    if (process.argv.length !== 3) throw new Error('Expected exactly one JSON file argument');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input) ||
        !Array.isArray(input.versions)) throw new Error('Expected an object with a versions array and range string');
    const clauses = parseRange(input.range);
    const entries = [];
    for (let i = 0; i < input.versions.length; i++) {
      if (!Object.hasOwn(input.versions, i)) throw new Error('Versions must be a dense array');
      entries.push({ text: input.versions[i], parsed: parse(input.versions[i]), index: i });
    }
    entries.sort((a, b) => compareParsed(a.parsed, b.parsed) || a.index - b.index);
    const sorted = entries.map(entry => entry.text);
    const satisfying = entries.filter(entry => satisfiesParsed(entry.parsed, clauses)).map(entry => entry.text);
    process.stdout.write(JSON.stringify({ sorted, satisfying }) + '\n');
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  runCli();
}
