+    return clause.trim().split(/\s+/).map(text => {
+      const match = /^(<=|>=|=|<|>)?(.*)$/.exec(text);
+      return { operator: match[1] ?? '=', version: parse(match[2]) };
+    });
+  });
+}
+
+function satisfiesParsed(version, clauses) {
+  return clauses.some(clause => {
+    if (version.prerelease.length && !clause.some(comparator =>
+      comparator.version.prerelease.length &&
+      CORE.every(key => version[key] === comparator.version[key]))) return false;
+    return clause.every(comparator => {
+      const result = compareParsed(version, comparator.version);
+      switch (comparator.operator) {
+        case '=': return result === 0;
+        case '<': return result < 0;
+        case '<=': return result <= 0;
+        case '>': return result > 0;
+        case '>=': return result >= 0;
+      }
+    });
+  });
+}
+
+export function satisfies(version, range) {
+  return satisfiesParsed(parse(version), parseRange(range));
+}
+
+function runCli() {
+  try {
+    if (process.argv.length !== 3) throw new Error('Expected exactly one JSON file argument');
+    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
+    if (input === null || typeof input !== 'object' || Array.isArray(input) ||
+        !Array.isArray(input.versions)) throw new Error('Expected an object with a versions array and range string');
+    const clauses = parseRange(input.range);
+    const entries = [];
+    for (let i = 0; i < input.versions.length; i++) {
+      if (!Object.hasOwn(input.versions, i)) throw new Error('Versions must be a dense array');
+      entries.push({ text: input.versions[i], parsed: parse(input.versions[i]), index: i });
+    }
+    entries.sort((a, b) => compareParsed(a.parsed, b.parsed) || a.index - b.index);
+    const sorted = entries.map(entry => entry.text);
+    const satisfying = entries.filter(entry => satisfiesParsed(entry.parsed, clauses)).map(entry => entry.text);
+    process.stdout.write(JSON.stringify({ sorted, satisfying }) + '\n');
+  } catch (error) {
+    process.stderr.write(`${error.message}\n`);
+    process.exitCode = 2;
+  }
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
+  runCli();
+}

